SELECT "dispat"."m_id", "Bio"."activity", "Bio"."activity", COUNT("dispat"."m_id"), MIN("rel12"."in_id"), COUNT("rel12"."in_id")
FROM "rel12" LEFT JOIN "dispat" ON "rel12"."m_id" = "dispat"."m_id" LEFT JOIN "rel11" ON "dispat"."m_id" = "rel11"."m_id" JOIN "Bio" ON "rel11"."b_id" = "Bio"."b_id" WHERE "dispat"."age" != '6' AND "dispat"."m_id" < 5 GROUP BY "dispat"."m_id", "Bio"."activity", "Bio"."activity" HAVING COUNT("rel12"."in_id") > 29 ORDER BY COUNT("dispat"."m_id") DESC, COUNT("rel12"."in_id") ASC LIMIT 726;

SELECT "rel12"."in_id", "indis"."tbil", "rel12"."m_id", COUNT("rel11"."m_id")
FROM "rel12" LEFT JOIN "dispat" ON "rel12"."m_id" = "dispat"."m_id" LEFT JOIN "rel11" ON "dispat"."m_id" = "rel11"."m_id" JOIN "indis" ON "rel12"."in_id" = "indis"."in_id" WHERE "indis"."tbil" = '1' AND "indis"."got" != '4' AND "rel11"."m_id" != 482 AND "indis"."got" != '0' GROUP BY "rel12"."in_id", "indis"."tbil", "rel12"."m_id" HAVING COUNT("rel11"."m_id") > 84 LIMIT 173;

SELECT "rel12"."m_id", "dispat"."age", AVG("rel12"."in_id")
FROM "indis" JOIN "rel12" ON "indis"."in_id" = "rel12"."in_id" JOIN "dispat" ON "rel12"."m_id" = "dispat"."m_id" WHERE "rel12"."m_id" < 35 AND "rel12"."in_id" >= 2847 AND "indis"."in_id" = 2226 AND "rel12"."in_id" <= 2628 AND "rel12"."in_id" <= 4915 GROUP BY "rel12"."m_id", "dispat"."age" LIMIT 604;

SELECT "rel12"."in_id", "indis"."ztt", "indis"."dbil", MAX("indis"."in_id"), MAX("rel12"."m_id"), SUM("indis"."in_id")
FROM "indis" LEFT JOIN "rel12" ON "indis"."in_id" = "rel12"."in_id" WHERE "rel12"."in_id" >= 3720 OR "indis"."tp" != '2' OR "indis"."alb" != '1' GROUP BY "rel12"."in_id", "indis"."ztt", "indis"."dbil" LIMIT 473;

SELECT "rel11"."b_id", "rel11"."b_id", MIN("Bio"."b_id")
FROM "Bio" LEFT JOIN "rel11" ON "Bio"."b_id" = "rel11"."b_id" WHERE "rel11"."m_id" != 311 GROUP BY "rel11"."b_id", "rel11"."b_id" HAVING MIN("Bio"."b_id") > 82 ORDER BY "rel11"."b_id" DESC, "rel11"."b_id" ASC;

SELECT "rel13"."m_id", "Bio"."b_id", "dispat"."age", "rel13"."m_id", COUNT("rel11"."b_id"), AVG("rel13"."a_id")
FROM "Bio" LEFT JOIN "rel11" ON "Bio"."b_id" = "rel11"."b_id" JOIN "dispat" ON "rel11"."m_id" = "dispat"."m_id" LEFT JOIN "rel13" ON "dispat"."m_id" = "rel13"."m_id" WHERE "Bio"."activity" = '3' GROUP BY "rel13"."m_id", "Bio"."b_id", "dispat"."age", "rel13"."m_id" HAVING COUNT("rel11"."b_id") > 40 ORDER BY "dispat"."age" DESC, "rel13"."m_id" ASC LIMIT 792;

SELECT "rel13"."m_id", "dispat"."sex", SUM("dispat"."m_id"), MIN("dispat"."m_id"), AVG("rel13"."m_id")
FROM "rel11" LEFT JOIN "dispat" ON "rel11"."m_id" = "dispat"."m_id" JOIN "rel13" ON "dispat"."m_id" = "rel13"."m_id" JOIN "Bio" ON "rel11"."b_id" = "Bio"."b_id" WHERE "dispat"."sex" = '0' GROUP BY "rel13"."m_id", "dispat"."sex" HAVING SUM("dispat"."m_id") > 52 LIMIT 472;

